SELECT
    P.ID_PESSOA,
    PDC.CPF_PESSOA CPF,
    HN.NOME,
    PV.ID_PESSOA_VINCULO,
    F.ID_FUNCIONARIO,
    FI.ID_FUNCIONARIO,
    FP.ID_FUNCIONARIO_PERFIL,
    FL.ID_FUNC_LOTACAO,
    FP.DATA_INICIO,
    FP.DATA_FIM,
    P.ID_DIVISAO,
    P.ID_SITUACAO,
    'INSERT INTO SW_FUESPI.PESSOA_VINCULO (ID_PESSOA_VINCULO, ID_PESSOA, ID_VINCULO, COD_INSTITUCIONAL, DATA_CADASTRO) VALUES (SW_FUESPI.SQ_PK_PESSOA_VINCULO.NEXTVAL, ' || P.ID_PESSOA || ', 2, ''000000-0'', ''08/09/2025'');' INSERT_PESSOA_VINCULO
    --'INSERT INTO SW_FUESPI.FUNCIONARIO (ID_FUNCIONARIO, ID_PESSOA_VINCULO, DATA_CADASTRO) VALUES (SW_FUESPI.SQ_PK_FUNCIONARIO.NEXTVAL, ' || PV.ID_PESSOA_VINCULO || ', ''08/09/2025'');' INSERT_FUNCIONARIO
