--        WHEN 861 THEN 'INSERT INTO SW_FUESPI.FUNCIONARIO_PERFIL (ID_FUNCIONARIO_PERFIL, ID_FUNCIONARIO, ID_PERFIL, DATA_CADASTRO, DATA_INICIO, ID_TIPO_FUNCIONARIO, ID_ESB_CATEG_TRABALHADOR, ID_MOVIMENTACAO, ID_REMUNERACAO, ID_TIPO_INCIDENCIA) VALUES (SW_FUESPI.SQ_PK_FUNCIONARIO_PERFIL.NEXTVAL, ' || F.ID_FUNCIONARIO || ', 1000101, ''08/09/2025'', ''01/09/2025'', 1000000, 69, 5, 1, 3);' -- S�o Jos� do Peixe
--    END INSERT_PERFIL
    --'INSERT INTO SW_FUESPI.FUNCIONARIO_INGRESSO (ID_FUNCIONARIO, DATA_CADASTRO, DATA_EXERCICIO, DATA_NOMEACAO, DATA_POSSE, ID_REGIME, ID_FUNCIONARIO_PERFIL, ID_ESPECIALIDADE) VALUES (' || F.ID_FUNCIONARIO || ', ''08/09/2025'', ''01/09/2025'', ''01/09/2025'', ''01/09/2025'', 3, ' || FP.ID_FUNCIONARIO_PERFIL || ', 1);' INSERT_INGRESSO
    --'INSERT INTO SW_FUESPI.FUNC_LOTACAO (ID_FUNC_LOTACAO, ID_FUNCIONARIO, ID_LOTACAO, DATA_CADASTRO, DATA_INICIO) VALUES (SW_FUESPI.SQ_PK_FUNC_LOTACAO.NEXTVAL, ' || F.ID_FUNCIONARIO || ', 1000000, ''08/09/2025'', ''01/09/2025'');' INSERT_LOTACAO
FROM
    SW_PUBLICO.PESSOA P
    JOIN SW_PUBLICO.PESSOA_DOC_CPF PDC ON PDC.ID_PESSOA = P.ID_PESSOA AND PDC.DATA_BAIXA IS NULL
    JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = P.ID_PESSOA AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PE ON PE.ID_PESSOA = P.ID_PESSOA
    LEFT JOIN SW_FUESPI.PESSOA_VINCULO PV ON PV.ID_PESSOA = P.ID_PESSOA
    LEFT JOIN SW_FUESPI.FUNCIONARIO F ON F.ID_PESSOA_VINCULO = PV.ID_PESSOA_VINCULO
    LEFT JOIN SW_FUESPI.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = F.ID_FUNCIONARIO
    LEFT JOIN SW_FUESPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = F.ID_FUNCIONARIO
    LEFT JOIN SW_FUESPI.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = F.ID_FUNCIONARIO
    LEFT JOIN SW_FUESPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
